#
# TABLE STRUCTURE FOR: Campuses
#

DROP TABLE IF EXISTS `Campuses`;

CREATE TABLE `Campuses` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `Campus` text DEFAULT NULL,
  `Location` text DEFAULT NULL,
  `County` text DEFAULT NULL,
  `Year` int(11) DEFAULT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=10001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: csu_fees
#

DROP TABLE IF EXISTS `csu_fees`;

CREATE TABLE `csu_fees` (
  `Campus` int(11) NOT NULL AUTO_INCREMENT,
  `Year` int(11) DEFAULT NULL,
  `CampusFee` int(11) DEFAULT NULL,
  PRIMARY KEY (`Campus`),
  CONSTRAINT `csu_fees_ibfk_1` FOREIGN KEY (`Campus`) REFERENCES `Campuses` (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=10001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: degrees
#

DROP TABLE IF EXISTS `degrees`;

CREATE TABLE `degrees` (
  `Year` int(11) NOT NULL,
  `Campus` int(11) NOT NULL,
  `Degrees` int(11) DEFAULT NULL,
  PRIMARY KEY (`Year`,`Campus`),
  KEY `Campus` (`Campus`),
  CONSTRAINT `degrees_ibfk_1` FOREIGN KEY (`Campus`) REFERENCES `Campuses` (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: discipline_enrollments
#

DROP TABLE IF EXISTS `discipline_enrollments`;

CREATE TABLE `discipline_enrollments` (
  `Campus` int(11) NOT NULL,
  `Discipline` int(11) NOT NULL,
  `Year` int(11) DEFAULT NULL,
  `Undergraduate` int(11) DEFAULT NULL,
  `Graduate` int(11) DEFAULT NULL,
  PRIMARY KEY (`Campus`,`Discipline`),
  CONSTRAINT `discipline_enrollments_ibfk_1` FOREIGN KEY (`Campus`) REFERENCES `Campuses` (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: enrollments
#

DROP TABLE IF EXISTS `enrollments`;

CREATE TABLE `enrollments` (
  `Campus` int(11) NOT NULL,
  `Year` int(11) NOT NULL,
  `TotalEnrollment_AY` int(11) DEFAULT NULL,
  `FTE_AY` int(11) DEFAULT NULL,
  PRIMARY KEY (`Campus`,`Year`),
  CONSTRAINT `enrollments_ibfk_1` FOREIGN KEY (`Campus`) REFERENCES `Campuses` (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: faculty
#

DROP TABLE IF EXISTS `faculty`;

CREATE TABLE `faculty` (
  `Campus` int(11) DEFAULT NULL,
  `Year` int(11) DEFAULT NULL,
  `Faculty` double DEFAULT NULL,
  KEY `Campus` (`Campus`),
  CONSTRAINT `faculty_ibfk_1` FOREIGN KEY (`Campus`) REFERENCES `Campuses` (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



